import styled from '@emotion/styled';
import { Tooltip } from '@hexa-ui/components2';

const borderTertiary = '#14141414';

export const StyledCampaignsContainer = styled.div({
  display: 'flex',
  flexDirection: 'column',
  width: '100%',
  height: '100%',
  justifyContent: 'center',
});

interface StyledCampaignsItemProps {
  $isLast?: boolean;
}

export const StyledCampaignsItem = styled.div<StyledCampaignsItemProps>(
  ({ $isLast }) => ({
    textAlign: 'center',
    width: '100%',
    textOverflow: 'ellipsis',
    overflow: 'hidden',
    whiteSpace: 'nowrap',
    padding: '0 12px',
    minHeight: '36px',
    maxHeight: '36px',
    borderBottom: `1px solid ${borderTertiary}`,
    ...($isLast === true && {
      borderBottom: 'none',
    }),
  }),
);

export const StyledTooltip = styled(Tooltip)({
  zIndex: 9999,
  // Prevent layout shifts that can cause ResizeObserver loops
  '& [data-radix-popper-content-wrapper]': {
    transform: 'translate3d(0, 0, 0)', // Force hardware acceleration
    willChange: 'transform', // Optimize for frequent changes
  },
});

export const StyledAgCellContent = styled.div({
  height: '100%',
  borderBottom: `1px solid ${borderTertiary}`,
  borderRight: `1px solid ${borderTertiary}`,
});
